public static class ObservableCompletionDesigner{public static IReadOnlyList<CompletionOpening> Generate(string runId,string reservoir,LogObservationArtifact log,CompletionDesignOptions o){o.Validate();if(string.IsNullOrWhiteSpace(reservoir)||reservoir.Length>200)throw new RunStageFailureException("ReservoirIdentityInvalid","Reservoir invalid.");if(log.Samples.Count<2)throw new RunStageFailureException("NoQualifyingObservableInterval","Log coverage insufficient.");double spacing=log.Samples.Zip(log.Samples.Skip(1),(a,b)=>b.MeasuredDepthM-a.MeasuredDepthM).Where(x=>x>0).DefaultIfEmpty(0).Min();if(spacing<=0)throw new RunStageFailureException("ObservableLogInvalid","Log MD invalid.");var spans=new List<(double T,double B)>();int start=-1;for(int i=0;i<log.Samples.Count;i++){bool yes=Qualifies(log.Samples[i],o);if(yes&&start<0)start=i;if((!yes||i==log.Samples.Count-1)&&start>=0){int end=yes&&i==log.Samples.Count-1?i:i-1;double t=Math.Max(log.Samples[0].MeasuredDepthM,log.Samples[start].MeasuredDepthM-spacing/2),b=Math.Min(log.Samples[^1].MeasuredDepthM,log.Samples[end].MeasuredDepthM+spacing/2);if(b-t>=o.MinimumContiguousThicknessM)spans.Add((t,b));start=-1;}}var merged=new List<(double T,double B)>();foreach(var x in spans){if(merged.Count>0&&x.T-merged[^1].B<=o.MergeGapM){var p=merged[^1];merged[^1]=(p.T,x.B);}else merged.Add(x);}if(merged.Count==0)throw new RunStageFailureException("NoQualifyingObservableInterval","No observable completion interval qualifies.");var result=new List<CompletionOpening>();for(int i=0;i<merged.Count;i++){var x=merged[i];result.Add(Make(x.B-x.T>=o.OpenHoleThicknessThresholdM?"OpenHole":"Perforated",x.T,x.B,i));if(i+1<merged.Count){double gap=merged[i+1].T-x.B;if(gap>=o.MinimumIsolationThicknessM&&gap<=o.MaximumIsolationGapM)result.Add(Make("Isolated",x.B,merged[i+1].T,i));}}if(result.Count>o.MaximumOpenings)throw new RunStageFailureException("CompletionOpeningLimitExceeded","Too many openings.");return result;CompletionOpening Make(string