public static class CompletionCanonicalization
{
 public static string CanonicalRequestJson(string pathBindingId,string completionModelVersion,IReadOnlyList<CompletionOpening> openings)
 {
  var canonicalOpenings=openings.Select(x=>new CanonicalOpening(x.OpeningId,x.ReservoirName,TypeValue(x.Type),x.TopMdM,x.BaseMdM,x.WellboreRadiusM,x.Skin,x.Efficiency,x.UncertaintyM)).ToArray();
  return JsonSerializer.Serialize(new CanonicalRequest(pathBindingId,completionModelVersion,canonicalOpenings),new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});
 }
 public static string CanonicalRequestHash(string pathBindingId,string completionModelVersion,IReadOnlyList<CompletionOpening> openings)=>DeterministicIdentity.Sha256(CanonicalRequestJson(pathBindingId,completionModelVersion,openings));
 private static int TypeValue(string value)=>value switch{"Perforated"=>0,"OpenHole"=>1,"Isolated"=>2,_=>throw new ArgumentException("Unsupported completion opening type.",nameof(value))};
 private sealed record CanonicalRequest(string PathBindingId,string CompletionModelVersion,IReadOnlyList<CanonicalOpening> Openings);
 private sealed record CanonicalOpening(string OpeningId,string ReservoirName,int Type,double TopMdM,double BaseMdM,double WellboreRadiusM,double Skin,double Efficiency,double UncertaintyM);
